vulnerableCode.code:
// VULNERABLE - the code is concatenated into SQL; the page reveals only FOUND / NOT FOUND
const sql = "SELECT id FROM reset_codes WHERE code = '" + code + "'";
const found = db.prepare(sql).get() != null; // one bit - but that is all the attacker needs
res.send(found ? 'Reset code is active' : 'No matching request');

secureCode.code:
// SECURE - bind the value; input can never become SQL, so there is no oracle to steer
const found = db.prepare('SELECT id FROM reset_codes WHERE code = ?').get(code) != null;
res.send(found ? 'Reset code is active' : 'No matching request');
// A generic response does NOT save a concatenated query - the fix is binding. Add least privilege:
